with open('/home/claude/trabalho/dados_armin_strom.txt', 'w', encoding='utf-8') as f:
    for n, c, u, e in R:
        assert '|' not in n + c + u + e, n
        f.write(f'{n}|{c}|{u}|{e}\n')
import collections
d = [k for k, v in collections.Counter(r[0] for r in R).items() if v > 1]
print(len(R), 'linhas; nomes repetidos:', d)
cods = [k for k, v in collections.Counter(r[1].replace('.', '').replace('-', '') for r in R if r[1]).items() if v > 1]
print('códigos repetidos:', cods)
